import React, { useEffect, useRef, useState } from 'react';
import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader';
import { OrbitControls } from 'three/examples/jsm/controls/OrbitControls';

const GlbTest = () => {
  const canvasRef = useRef(null);
  const [mixer, setMixer] = useState(null);
  const [animationAction, setAnimationAction] = useState(null);
  const [isPlaying, setIsPlaying] = useState(false);
  const [renderer, setRenderer] = useState(null);
  const [camera, setCamera] = useState(null);

  useEffect(() => {
    let animationFrameId;
    const scene = new THREE.Scene();
    const newCamera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
    setCamera(newCamera);
    const newRenderer = new THREE.WebGLRenderer({ antialias: true });

    newRenderer.setSize(window.innerWidth, window.innerHeight);
    newRenderer.shadowMap.enabled = true;
    newRenderer.shadowMap.type = THREE.PCFSoftShadowMap;
    canvasRef.current.appendChild(newRenderer.domElement);
    setRenderer(newRenderer);

    const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
    scene.add(ambientLight);

    const directionalLight = new THREE.DirectionalLight(0xffffff, 0.8);
    directionalLight.position.set(2, 2, 2);
    directionalLight.castShadow = true;
    directionalLight.shadow.mapSize.width = 1024;
    directionalLight.shadow.mapSize.height = 1024;
    directionalLight.shadow.camera.near = 0.5;
    directionalLight.shadow.camera.far = 50;
    scene.add(directionalLight);

    const fillLight = new THREE.DirectionalLight(0xffffff, 0.4);
    fillLight.position.set(-1, -1, 2);
    scene.add(fillLight);

    const loader = new GLTFLoader();
    loader.load('/static/models/body__animated_test_something.glb', (gltf) => {
      const model = gltf.scene;
      model.traverse((node) => {
        if (node.isMesh) {
          node.castShadow = true;
          node.receiveShadow = true;
        }
      });
      scene.add(model);

      const newMixer = new THREE.AnimationMixer(model);
      setMixer(newMixer);

      if (gltf.animations.length > 0) {
        const action = newMixer.clipAction(gltf.animations[0]);
        setAnimationAction(action);
        action.play();
        setIsPlaying(true);
      }

      const box = new THREE.Box3().setFromObject(model);
      const center = box.getCenter(new THREE.Vector3());
      const size = box.getSize(new THREE.Vector3());

      newCamera.position.set(center.x, center.y, size.z * 2);
      newCamera.lookAt(center);
    }, undefined, (error) => {
      console.error('Error loading GLB file:', error);
    });

    const controls = new OrbitControls(newCamera, newRenderer.domElement);
    controls.update();

    let lastTime = 0;
    const animate = (time) => {
      const delta = (time - lastTime) / 1000;
      lastTime = time;

      if (mixer) {
        mixer.update(delta);
      }

      controls.update();
      newRenderer.render(scene, newCamera);
      animationFrameId = requestAnimationFrame(animate);
    };

    animate(0);

    const handleResize = () => {
      const width = window.innerWidth;
      const height = window.innerHeight;
      newRenderer.setSize(width, height);
      newCamera.aspect = width / height;
      newCamera.updateProjectionMatrix();
    };

    window.addEventListener('resize', handleResize);

    return () => {
      window.removeEventListener('resize', handleResize);
      cancelAnimationFrame(animationFrameId);
      if (newRenderer) {
        newRenderer.dispose();
      }
    };
  }, []);

  const toggleAnimation = () => {
    if (animationAction) {
      if (isPlaying) {
        animationAction.stop();
      } else {
        animationAction.play();
      }
      setIsPlaying(!isPlaying);
    }
  };

  return (
    <div style={{ width: '90vw', height: '90vh', overflow: 'hidden' }}>
      <div ref={canvasRef} style={{ width: '90%', height: '90%' }} />
      <button 
        onClick={toggleAnimation}
        style={{
          position: 'absolute',
          bottom: '20px',
          left: '50%',
          transform: 'translateX(-50%)',
          padding: '10px 20px',
          fontSize: '16px'
        }}
      >
        {isPlaying ? 'Pause Animation' : 'Play Animation'}
      </button>
    </div>
  );
};

export default GlbTest;
